	FROM custinfo ci WITH(NOLOCK) 
	WHERE NOT EXISTS (SELECT 1 FROM ProblemAccountClassification pc WITH(NOLOCK) WHERE pc.custid = ci.custid)
		AND ci.customerClass BETWEEN 8 AND 13
